const { exec } = require('child_process');
const fs = require('fs');
const path = require('path');

const uri = 'mongodb+srv://<user>:<password>@<cluster-name>/<database-name>';
const backupDir = './backup';

// Ensure backup directory exists
if (!fs.existsSync(backupDir)) {
  fs.mkdirSync(backupDir);
}

const timestamp = new Date().toISOString().replace(/[^0-9]/g, '');
const backupPath = path.join(backupDir, timestamp);

exec(`mongodump --uri "${uri}" --out "${backupPath}"`, (error, stdout, stderr) => {
  if (error) {
    console.error(`Backup failed: ${error.message}`);
    return;
  }
  if (stderr) {
    console.error(`Backup stderr: ${stderr}`);
    return;
  }
  console.log(`Backup successful: ${stdout}`);
});
```

To schedule this script daily, add a cron job (e.g., `0 2 * * * /usr/bin/node /path/to/script.js`). Ensure `mongodump` is installed and accessible in your environment.
